From 3dc8bfb8adcd97189a0ed5edae774f78cef8ef57 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:19:50 +0100
Subject: [PATCH] applets/notes: don't block startup with large notes

Pasted text ends up in one paragraph with line breaks, which Qt Quick
lays out and renders as a whole, and resizes during startup lay it out
again each time. Load line breaks as paragraphs and set the text once.

BUG: 499057
---
 applets/notes/filesystemnoteloader.cpp | 45 +++++++++++++++++++++++++-
 applets/notes/qml/main.qml             | 12 +++++--
 2 files changed, 53 insertions(+), 4 deletions(-)

diff --git a/applets/notes/filesystemnoteloader.cpp b/applets/notes/filesystemnoteloader.cpp
index bd691599d..78bd0f034 100644
--- a/applets/notes/filesystemnoteloader.cpp
+++ b/applets/notes/filesystemnoteloader.cpp
@@ -11,6 +11,9 @@

 #include <QDebug>
 #include <QStandardPaths>
+#include <QTextBlock>
+#include <QTextCursor>
+#include <QTextDocument>
 #include <QUuid>

 #include <KDirWatch>
@@ -94,11 +97,51 @@ FileNote::FileNote(const QString &path, const QString &id)
     load();
 }

+// Turn line breaks into paragraphs: text in one huge paragraph is laid out
+// and rendered as a whole, which takes a very long time for large notes
+static QString splitLineBreaks(const QString &html)
+{
+    if (!html.contains(QLatin1String("<br"), Qt::CaseInsensitive)) {
+        return html;
+    }
+
+    QTextDocument document;
+    document.setHtml(html);
+
+    QTextCursor cursor(&document);
+    cursor.beginEditBlock();
+    for (QTextBlock block = document.lastBlock(); block.isValid(); block = block.previous()) {
+        if (block.textList()) {
+            continue;
+        }
+        const QString text = block.text();
+        for (qsizetype i = text.lastIndexOf(QChar::LineSeparator); i >= 0; i = text.lastIndexOf(QChar::LineSeparator, i - 1)) {
+            cursor.setPosition(block.position() + i);
+            cursor.setPosition(block.position() + i + 1, QTextCursor::KeepAnchor);
+            cursor.removeSelectedText();
+
+            QTextBlockFormat format = cursor.blockFormat();
+            QTextBlockFormat newFormat = format;
+            newFormat.setTopMargin(0);
+            newFormat.setTextIndent(0);
+            format.setBottomMargin(0);
+            cursor.setBlockFormat(format);
+            cursor.insertBlock(newFormat, cursor.charFormat());
+            if (i == 0) {
+                break;
+            }
+        }
+    }
+    cursor.endEditBlock();
+
+    return document.toHtml();
+}
+
 void FileNote::load()
 {
     QFile file(m_path);
     if (file.open(QIODevice::ReadOnly | QIODevice::Text)) {
-        setNoteText(QString::fromUtf8(file.readAll()));
+        setNoteText(splitLineBreaks(QString::fromUtf8(file.readAll())));
     }
 }

diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..2d5b431eb 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -44,6 +44,8 @@ PlasmoidItem {
     property bool noBackground: false // binding in onCompleted to avoid binding loop

     property Note note: noteManager.loadNote(Plasmoid.configuration.noteId, Plasmoid.id);
+    // Only set the text once the applet has its final size, as every resize lays out the whole text again
+    property bool textLoaded: false

     // define colors used for icons in ToolButtons and for text in TextArea.
     // this is deliberately _NOT_ the theme color as we are over a known bright background!
@@ -65,6 +67,7 @@ PlasmoidItem {
         // if we dropped a text file, we want its contents,
         // otherwise we take the external data verbatim
         var contents = NotesHelper.fileContents(data) || data
+        textLoaded = true
         mainTextArea.text = String(contents).replace(/\n/g, "<br>") // what about richtext?

         // place cursor at the end of text
@@ -103,7 +106,7 @@ PlasmoidItem {
     Component.onDestruction: {
         if (scheduledForDestruction) {
             noteManager.deleteNoteResources(note.id);
-        } else {
+        } else if (textLoaded) {
             note.save(mainTextArea.text);
         }
     }
@@ -260,7 +263,7 @@ PlasmoidItem {
                         target: mainTextArea
                         property: "text"
                         value: root.note.noteText
-                        when: !mainTextArea.activeFocus
+                        when: root.textLoaded && !mainTextArea.activeFocus
                         // don't restore an empty value (which IS empty by default when the applet starts up),
                         // instead only remove this binding for the time when the user edits the content.
                         restoreMode: Binding.RestoreBinding
@@ -440,7 +443,10 @@ PlasmoidItem {

                 // Give it some time to lay out the text, because at this
                 // point in time content size is not reliable yet.
-                Component.onCompleted: Qt.callLater(restoreScroll)
+                Component.onCompleted: Qt.callLater(() => {
+                    root.textLoaded = true;
+                    Qt.callLater(restoreScroll);
+                })
                 Component.onDestruction: saveScroll()
             }

